INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7223446, 1113873, 43463, '<td valign="top">Voted earlier, bumping up, and coming back to comment.<br/> <br/>Fantastic zoomed in close-up of the center of this flower. The yellow and reds are very bold and vibrant. Love the details seen from the dewdrops to the petal texture to the details of the red radial fan of the center. Composition is also very pleasing where you have the stigma (I think that is what the exuding center ''stem'' is called) coming out at a diagonal to the bottom right portion of the frame. You really give your audience a lovely and colorful close-up of this flower. Well done.</td>', 'Voted earlier, bumping up, and coming back to comment. Fantastic zoomed in close-up of the center of this flower. The yellow and reds are very bold and vibrant. Love the details seen from the dewdrops to the petal texture to the details of the red radial fan of the center. Composition is also very pleasing where you have the stigma (I think that is what the exuding center ''stem'' is called) coming out at a diagonal to the bottom right portion of the frame. You really give your audience a lovely and colorful close-up of this flower. Well done.', '2014-06-01 21:37:50.000000', NULL, 1),
(7223449, 1113704, 12611, '<td valign="top">great depth- good light.</td>', 'great depth- good light.', '2014-06-01 21:42:58.000000', NULL, 1),
(7223450, 1113240, 12611, '<td valign="top">Love the perspective and juxtaposition.</td>', 'Love the perspective and juxtaposition.', '2014-06-01 21:43:30.000000', NULL, 1),
(7223451, 1113537, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>I love the light on this floral shot - it shows off the delicate hues of the pinks. I do like the bokeh in the backdrop for those pastel hues of the natural environment complement the flower, but I think that there is too much negative space. I think the composition would be even stronger if you zoomed in closer to the first flower in the foreground such that it now fills a 1/3 of the frame on the left side. The flower in the backdrop would still be in the frame but appear in the far right - and you should not lose those fabulous green/yellow bokeh circles I see in the top part of the composition. Get at a slightly lower angle to shoot up at the flowers so those bokeh circles would then dominate the full backdrop. Just my two cents.</td>', 'Voted earlier coming back to comment. I love the light on this floral shot - it shows off the delicate hues of the pinks. I do like the bokeh in the backdrop for those pastel hues of the natural environment complement the flower, but I think that there is too much negative space. I think the composition would be even stronger if you zoomed in closer to the first flower in the foreground such that it now fills a 1/3 of the frame on the left side. The flower in the backdrop would still be in the frame but appear in the far right - and you should not lose those fabulous green/yellow bokeh circles I see in the top part of the composition. Get at a slightly lower angle to shoot up at the flowers so those bokeh circles would then dominate the full backdrop. Just my two cents.', '2014-06-01 21:43:37.000000', NULL, 1),
(7223452, 1113474, 12611, '<td valign="top">like blond hair over one''s lover''s shoulder.</td>', 'like blond hair over one''s lover''s shoulder.', '2014-06-01 21:44:17.000000', NULL, 1),
